// === Tab: mySketch.js ===
const vertexShader = `
precision lowp float;
attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec4 aVertexColor;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
varying vec2 vTexCoord;
varying vec4 vVertexColor;


void main() {
  // Apply the camera transform
  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * viewModelPosition;  
  // Pass along data to the fragment shader
  vTexCoord = aTexCoord;
  vVertexColor = aVertexColor;
}`;

const fragmentShader = `
precision lowp float;

#define PI 3.14159265359
#define PI2 6.28318530718

uniform float u_time;
uniform vec2 u_resolution;
uniform sampler2D u_texture;

varying vec2 vTexCoord;


void main() {
  vec2 coord = vTexCoord;
    coord.y -= 0.001;
  vec4 color = texture2D(u_texture, coord);

  gl_FragColor = color;
}`;

let myShader;
let next;
let prev;
let pair = true;
let topLeft
let bottomRight;

function preload() {
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  frameRate(30);

  myShader = createShader(vertexShader,fragmentShader);

  topLeft = createVector(-windowWidth / 2, -windowHeight / 2);
  bottomRight = createVector(windowWidth / 2, windowHeight / 2);

  next = createFramebuffer({ format: FLOAT });
  prev = createFramebuffer({ format: FLOAT });

  next.begin();
  noStroke();

  for (let i = 0; i < 5000; i++) {
    fill(200, 200, 0);
    circle(
      random(topLeft.x,bottomRight.x),
      random(topLeft.y, bottomRight.y),
      5
    );
  }
  next.end();
}


function draw() {
  // Swap prev and next
  [prev, next] = [next, prev];

  next.begin();
  clear();

  shader(myShader);
  myShader.setUniform("u_time", frameCount);
  myShader.setUniform("u_screen_size", [windowWidth, windowHeight]);
  myShader.setUniform("u_texture", prev);
  noStroke();
  plane(windowWidth, windowHeight);4

  next.end();
  resetShader();

  background(22);
  image(next,topLeft.x, topLeft.y);


}

